export const TOUCH=Object.freeze([Object.freeze({key:"overview",station:"overview",hotkey:"1"}),Object.freeze({key:"desk",station:"desk",hotkey:"2"}),Object.freeze({key:"model",station:"model",hotkey:"3"}),Object.freeze({key:"menu",station:"menu",hotkey:"4"}),Object.freeze({key:"board",station:"board",hotkey:"5"}),Object.freeze({key:"printer",station:"printer",hotkey:"6"})]),COACHING=Object.freeze({retireAfter:3,calmSeconds:30}),USED=Object.freeze({desk:1,model:2,menu:4,board:8,printer:16});export function usedCount(t){let e=0;for(let n=t>>>0;n;n&=n-1)e++;return e}export function noteUsed(t,e){return Object.prototype.hasOwnProperty.call(USED,e)?(t|USED[e])>>>0:t>>>0}export function marksShown(t,e,n=COACHING){if(usedCount(t)>=n.retireAfter)return[];const r={desk:!0,model:!!(e&&e.own),menu:!!(e&&e.own),board:!!(e&&e.own),printer:!!(e&&e.own&&e.tasks)};return TOUCH.filter(o=>r[o.key]&&!(t&USED[o.key])).map(o=>o.key)}export function touchForKey(t){const e=TOUCH.find(n=>n.hotkey===t);return e?e.key:null}export function nextLevel(t,e){if(!t.length)return null;const n=t.indexOf(e);return n<0?t[0]:n+1<t.length?t[n+1]:null}export function onScreen(t,e=.06){return Number.isFinite(t.x)&&Number.isFinite(t.y)&&t.z>-1&&t.z<1&&Math.abs(t.x)<1-e&&Math.abs(t.y)<1-e}
